import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import formidable from 'formidable';
import { Readable } from 'stream';

// Helper to parse multipart form data using formidable in a promise
async function parseForm(req) {
  return new Promise((resolve, reject) => {
    const form = new formidable.IncomingForm();
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

console.log("hello image uploaded")

// Only use named HTTP method exports in App Router
export async function POST(req) {
  // formidable expects a Node.js IncomingMessage, which req is in app/api
  try {
    const { fields, files } = await parseForm(req);

    const gymId = fields.gym_id;
    const file = files.profilePicture;

    if (!gymId || !file) {
      return new Response(JSON.stringify({ error: 'Missing gym_id or file' }), { status: 400 });
    }

    // Read file as buffer
    const fs = require('fs');
    const data = fs.readFileSync(file.filepath);

    // Configure S3Client for Cloudflare R2
    const s3 = new S3Client({
      region: 'auto',
      endpoint: process.env.R2_ENDPOINT,
      credentials: {
        accessKeyId: process.env.R2_ACCESS_KEY_ID,
        secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,
      },
    });

    // Prepare upload parameters
    const putParams = {
      Bucket: process.env.R2_BUCKET,
      Key: `${gymId}`,
      Body: data,
      ContentType: file.mimetype,
    };

    // Upload to R2
    await s3.send(new PutObjectCommand(putParams));

    return new Response(JSON.stringify({ success: true, key: gymId }), { status: 200 });
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), { status: 500 });
  }
}

